const orders = $input.first().json.checkoutForms || [];
const result = [];

for (const order of orders) {
  const buyer = order.buyer || {};
  const delivery = order.delivery || {};
  const summary = order.summary || {};
  const deliveryAddress = delivery.address || {};

  // Czy to paczkomat/automat?
  const isPaczkomat = !!delivery.pickupPoint;

  // Dane kupującego (buyer)
  const buyerFirstName = buyer.firstName || '';
  const buyerLastName = buyer.lastName || '';

  // Dane dostawy (delivery.address)
  const deliveryFirstName = deliveryAddress.firstName || '';
  const deliveryLastName = deliveryAddress.lastName || '';

  // Pole "nazwisko do wysyłki":
  // - puste jeśli paczkomat
  // - puste jeśli takie samo jak kupujący
  let sheetDeliveryLastName = '';
  if (!isPaczkomat && deliveryLastName !== buyerLastName) {
    sheetDeliveryLastName = deliveryLastName;
  }

  // Kwota i waluta z summary.totalToPay (UWAGA: amount to string!)
  const totalToPay = parseFloat(summary.totalToPay?.amount) || 0;
  const totalCurrency = summary.totalToPay?.currency || 'PLN';

  // Telefon - z adresu dostawy (bez spacji)
  const phone = (deliveryAddress.phoneNumber || buyer.phoneNumber || '').replace(/\s/g, '');

  // Koszt wysyłki (amount to string!)
  const shippingCost = parseFloat(delivery.cost?.amount) || 0;

  // Data sprzedaży - z lineItems[0].boughtAt lub updatedAt
  const dataSprzedazy = order.lineItems?.[0]?.boughtAt || order.updatedAt || '';

  result.push({
    json: {
      ID: order.id,
      DataSprzedazy: dataSprzedazy,
      totalToPay: totalToPay,
      totalCurrency: totalCurrency,
      buyerFirstName: buyerFirstName,
      buyerLastName: buyerLastName,
      buyerLogin: buyer.login || '',
      deliveryFirstName: deliveryFirstName,
      deliveryLastName: deliveryLastName,
      sheetDeliveryLastName: sheetDeliveryLastName,
      street: deliveryAddress.street || '',
      city: deliveryAddress.city || '',
      zipCode: deliveryAddress.zipCode || '',
      countryCode: deliveryAddress.countryCode || 'PL',
      phone: phone,
      shippingCost: shippingCost,
      isPaczkomat: isPaczkomat,
      Market: 'All_mo'
    }
  });
}

return result.length > 0 ? result : [{ json: { empty: true } }];

