const items = $input.all();
const result = [];

for (const item of items) {
  const order = item.json;

  if (!order || !order.id) continue;

  const user = order.user || {};
  const deliveryAddress = user.deliveryAddress || {};
  const delivery = order.delivery || {};

  const totalAmount = (order.totalPrice || 0) / 100;
  const shippingCost = (delivery.price || 0) / 100;

  // Dane kupującego i dostawy
  const buyerFirstName = deliveryAddress.firstName || '';
  const buyerLastName = deliveryAddress.lastName || '';
  const deliveryFirstName = deliveryAddress.firstName || '';
  const deliveryLastName = deliveryAddress.lastName || '';

  // Pole do arkusza - puste jeśli takie same jak kupujący
  let sheetDeliveryLastName = '';
  if (deliveryLastName !== buyerLastName) {
    sheetDeliveryLastName = deliveryLastName;
  }

  result.push({
    json: {
      ID: order.id,
      DataSprzedazy: order.purchasedAt || order.created,
      totalToPay: totalAmount,
      totalCurrency: 'PLN',
      buyerFirstName: buyerFirstName,
      buyerLastName: buyerLastName,
      buyerLogin: '',
      deliveryFirstName: deliveryFirstName,
      deliveryLastName: deliveryLastName,
      sheetDeliveryLastName: sheetDeliveryLastName,
      street: deliveryAddress.address || (deliveryAddress.street + ' ' + (deliveryAddress.buildingNumber || '')).trim(),
      city: deliveryAddress.city || '',
      zipCode: deliveryAddress.zip || '',
      countryCode: (deliveryAddress.country || 'pl').toUpperCase(),
      phone: deliveryAddress.phone || '',
      shippingCost: shippingCost,
      Market: 'Erli'
    }
  });
}

return result.length > 0 ? result : [{ json: { empty: true } }];

const response = $input.first().json;
const orders = response.orders || [];
const result = [];

// Regex do wykrywania kodu paczkomatu (np. KLD03N, SZC55M)
const paczkomatRegex = /^[A-Z]{3}\d{2}[A-Z]$/;

for (const order of orders) {
  // Filtruj po statusie - pomijaj anulowane
  if (order.order_state === 'CANCELED') {
    continue;
  }

  const customer = order.customer || {};
  const shippingAddress = customer.shipping_address || {};

  let totalAmount = order.total_price || order.price || 0;
  let shippingCost = order.shipping_price || 0;

  // Mapowanie kodu kraju POL -> PL
  const rawCountry = shippingAddress.country_iso_code || 'POL';
  const countryCode = rawCountry === 'POL' ? 'PL' : rawCountry;

  // Sprawdź czy lastname w shipping_address to kod paczkomatu
  const shippingLastName = shippingAddress.lastname || '';
  const isPaczkomat = paczkomatRegex.test(shippingLastName);

  // Dane kupującego (buyer)
  const buyerFirstName = customer.firstname || '';
  const buyerLastName = customer.lastname || '';

  // Dane dostawy (delivery) - jeśli paczkomat, użyj danych kupującego
  let deliveryFirstName, deliveryLastName;
  if (isPaczkomat) {
    deliveryFirstName = buyerFirstName;
    deliveryLastName = buyerLastName;
  } else {
    deliveryFirstName = shippingAddress.firstname || buyerFirstName;
    deliveryLastName = shippingAddress.lastname || buyerLastName;
  }

  // Pole do arkusza "nazwisko do wysyłki":
  // - puste jeśli paczkomat
  // - puste jeśli takie samo jak kupujący
  // - deliveryLastName w przeciwnym razie
  let sheetDeliveryLastName = '';
  if (!isPaczkomat && deliveryLastName !== buyerLastName) {
    sheetDeliveryLastName = deliveryLastName;
  }

  result.push({
    json: {
      ID: order.order_id || order.commercial_id,
      DataSprzedazy: order.created_date,
      totalToPay: totalAmount,
      totalCurrency: order.currency_iso_code || 'PLN',
      buyerFirstName: buyerFirstName,
      buyerLastName: buyerLastName,
      buyerLogin: '',
      deliveryFirstName: deliveryFirstName,
      deliveryLastName: deliveryLastName,
      sheetDeliveryLastName: sheetDeliveryLastName,
      street: shippingAddress.street_1 || '',
      city: shippingAddress.city || '',
      zipCode: shippingAddress.zip_code || '',
      countryCode: countryCode,
      phone: shippingAddress.phone || '',
      shippingCost: shippingCost,
      Market: 'Empik'
    }
  });
}

return result.length > 0 ? result : [{ json: { empty: true } }];

const response = $input.first().json;
const orders = response.results || [];
const result = [];

if (response.isError) {
  return [{ json: { empty: true, error: response.messages } }];
}

for (const order of orders) {
  const customer = order.customer || {};

  // Oblicz sumę produktów Z VAT
  let totalAmount = 0;
  for (const product of order.products || []) {
    const qty = product.initial_qty || product.quantity || 1;
    const price = parseFloat(product.sale_price) || 0;
    const vat = parseFloat(product.vat) || 0;
    totalAmount += price * qty * (1 + vat);
  }

  // Dodaj koszt wysyłki (już zawiera VAT w eMAG)
  const shippingCost = order.shipping_tax || 0;
  const totalToPay = totalAmount + shippingCost;

  // Dane kupującego z customer.name
  const customerName = customer.name || '';
  const nameParts = customerName.split(' ');
  const buyerFirstName = nameParts[0] || '';
  const buyerLastName = nameParts.slice(1).join(' ') || '';

  // Dane dostawy z customer.shipping_contact
  const shippingContact = customer.shipping_contact || customerName;
  const contactParts = shippingContact.split(' ');
  const deliveryFirstName = contactParts[0] || '';
  const deliveryLastName = contactParts.slice(1).join(' ') || '';

  // Pole do arkusza - puste jeśli takie samo jak kupujący
  let sheetDeliveryLastName = '';
  if (deliveryLastName !== buyerLastName) {
    sheetDeliveryLastName = deliveryLastName;
  }

  // DANE ADRESOWE
  const street = customer.shipping_street || '';
  const city = customer.shipping_city || customer.shipping_locality_name || '';
  const zipCode = customer.shipping_postal_code || '';
  const phone = customer.shipping_phone || customer.phone_1 || '';

  result.push({
    json: {
      ID: 'EMAG_RO_' + order.id,
      DataSprzedazy: order.date || order.created,
      totalToPay: Math.round(totalToPay * 100) / 100,
      totalCurrency: 'RON',
      buyerFirstName: buyerFirstName,
      buyerLastName: buyerLastName,
      buyerLogin: customer.email || '',
      deliveryFirstName: deliveryFirstName,
      deliveryLastName: deliveryLastName,
      sheetDeliveryLastName: sheetDeliveryLastName,
      street: street,
      city: city,
      zipCode: zipCode,
      countryCode: 'RO',
      phone: phone,
      shippingCost: shippingCost,
      Market: 'eMAG_RO'
    }
  });
}

return result.length > 0 ? result : [{ json: { empty: true } }];

