function getPreviousWorkingDay() {
  const date = new Date();
  date.setDate(date.getDate() - 1);
  while (date.getDay() === 0 || date.getDay() === 6) {
    date.setDate(date.getDate() - 1);
  }
  return date.toISOString().split('T')[0];
}

const dataKursu = getPreviousWorkingDay();

return {
  json: {
    ...$input.item.json,
    currency: 'EUR',
    dataKursu: dataKursu,
    nbpUrl: `https://api.nbp.pl/api/exchangerates/rates/A/EUR/${dataKursu}/?format=json`
  }
};

