      flattenedOrders.push({
        json: {
          ...order,
          platform: 'Empik'  // dodaj platform identifier
        }
      });
    }
  }
}

return flattenedOrders;

// Pobierz istniejące wiersze z arkusza
const existingRows = $('Get Recent IDs').all();

// Cutoff - 5 godzin temu
const cutoff = new Date(Date.now() - 5 * 60 * 60 * 1000);

// Wyciągnij ID tylko z ostatnich 5h (filtruj po dacie)
const recentIds = existingRows
  .filter(row => {
    const dateStr = row.json['Data Sprzedaży'] || row.json['DataSprzedazy'] || '';
    if (!dateStr) return true;
    const date = new Date(dateStr);
    return date > cutoff;
  })
  .map(row => String(row.json.ID || ''));

// Nowe zamówienia z Merge All Sources
const newOrders = $('Merge All Sources').all();

// Zostaw tylko te, których ID nie ma w arkuszu
const uniqueOrders = newOrders.filter(order => {
  if (order.json.empty) return false;
  const orderId = String(order.json.ID || '');
  return !recentIds.includes(orderId);
});

console.log(`Istniejących ID (ostatnie 5h): ${recentIds.length}`);
console.log(`Nowych zamówień: ${newOrders.length}`);
